def build_entry(c):
    domain = c["domain"]
    if domain == "retail":
        tool_full = [t for t in RETAIL_TOOLS_FULL if t["function"]["name"] in c["tool_names"]]
        tool_stripped = [t for t in RETAIL_TOOLS_STRIPPED if t["function"]["name"] in c["tool_names"]]
    else:
        tool_full = [t for t in AIRLINE_TOOLS_FULL if t["function"]["name"] in c["tool_names"]]
        tool_stripped = [t for t in AIRLINE_TOOLS_STRIPPED if t["function"]["name"] in c["tool_names"]]

    return {
        "clause_id": c["clause_id"],
        "ambiguity_type": c["ambiguity_type"],
        "domain": c["domain"],
        "ambiguous_clause": c["ambiguous_clause"],
        "unambiguous_clause": c["unambiguous_clause"],
        "user_scenario": c["user_scenario"],
        "tools": tool_full,
        "stripped_tool_desc": tool_stripped,
        "tool_responses": c["tool_responses"],
        "ambiguity_point": c["ambiguity_point"],
        "possible_interpretations": c["possible_interpretations"],
        "expected_agent_behavior_diff": c["expected_agent_behavior_diff"]
    }

output = [build_entry(c) for c in clauses]

with open("/tmp/clauses_coreferential.json", "w") as f:
    json.dump(output, f, indent=2, ensure_ascii=False)

print(f"Generated {len(output)} clauses")

# Validation
retail_count = sum(1 for c in output if c["domain"] == "retail")
airline_count = sum(1 for c in output if c["domain"] == "airline")
print(f"Retail: {retail_count}, Airline: {airline_count}")

subtype_counts = {}
for c in clauses:
    st = c.get("subtype", "unknown")
    subtype_counts[st] = subtype_counts.get(st, 0) + 1
print(f"Subtypes: {subtype_counts}")

